import type {Loading, AnyObj} from '@smarttestpro/smart-common';
import {create, Api, ApiClient} from '@smarttestpro/smart-common';
import {getStudyBookTableContent} from '../../api/dashboard-api';

const SmartTestClient = ApiClient.getInstance('smart-test');
SmartTestClient.setEndpoint('https://api.smarttest.pro/api');

type StudyBookStore = {
  studyBookId: string;
  studyBookTableContent: AnyObj[];
  loading: Loading;
  saveLoading: Loading;
};

type StudyBookStoreAction = {
  getStudyBookTableContent: (studyBookId: string) => void;
};

const initValue: StudyBookStore = {
  studyBookId: '',
  studyBookTableContent: [],
  loading: 'none',
  saveLoading: 'none',
};

export const useStudyBookStore = create<
  StudyBookStore & StudyBookStoreAction
>()((set, _get) => ({
  ...initValue,

  getStudyBookTableContent: async (studyBookId: string) => {
    set({studyBookId: studyBookId, loading: 'loading'});
    try {
      const result = await getStudyBookTableContent(studyBookId);

      set({studyBookTableContent: result.data, loading: 'success'});
    } catch (error) {
      set({loading: 'error'});
    }
  },
}));
